import os
import re
from collections import OrderedDict
from zipfile import ZipFile

from taf.ul.bts_kpi_report_generator.Exception import KPINoFilesInDir
from taf.ul.bts_kpi_report_generator.parser.Parser import HASHParser, RTPMParser, XMLParser


class FilesParser(object):
    def __init__(self, path_dir, counters_need, generate_html_xml):
        """

        :param path_dir:
        :param counters_need:
        :param generate_html_xml:
        """
        if generate_html_xml:
            self.__counters_need = 'all'
        else:
            self.__counters_need = counters_need
        self.__path_dir = path_dir
        self.__paths_all_files = []
        self.__measurements = OrderedDict()

    @property
    def measurements(self):
        """

        :return:
        """
        return self.__measurements

    @property
    def path_dir(self):
        return self.__path_dir

    def parse_files(self):
        """

        :return:
        """
        if os.path.splitext(self.__path_dir)[-1].lower() == '.zip':
            if self.__check_zip_content() == "snapshot":
                self.__unzip_snapshot()
            else:
                self.__unzip_pm_stats()
        extensions = self.__scan_extension()
        extension = self.__get_proper_extension_scan_gz(extensions)
        path_files = self.__get_files(extension)
        file_parser = {'.pl': RTPMParser, '.xml': XMLParser, '.hash': HASHParser}

        for path_file in path_files:
            parser = file_parser[extension](path_file, self.__counters_need)
            parser.parse()
            for measurement in parser.measurements_file:
                self.__measurements[measurement] = parser.measurements_file[measurement]

    def __check_zip_content(self):
        with ZipFile(self.__path_dir, 'r') as zip_file:
            all_files = zip_file.namelist()
            for file in all_files:
                if '.zip' in file:
                    return "snapshot"
            return "pm_stats"

    def __unzip_pm_stats(self):
        with ZipFile(self.__path_dir, 'r') as zip_file:
            path_dir_without_zip_extension = self.__path_dir[:-4]
            zip_file.extractall(path_dir_without_zip_extension)
            self.__path_dir = path_dir_without_zip_extension

    def __unzip_snapshot(self):
        path_dir_new = self.__create_dir_snapshot()
        with ZipFile(self.__path_dir, 'r') as zip_file:
            last_zip_file = self.__select_zip_file_where_pmstats_are_located(zip_file)
            zip_file.extract(last_zip_file, path_dir_new)

        path_last_zip_file = os.path.join(path_dir_new, last_zip_file)

        with ZipFile(path_last_zip_file, 'r') as zip_file:
            files_pm_stats = zip_file.namelist()
            for file_gz in files_pm_stats:
                match = re.search(r'PM.BTS.*.xml.gz$', file_gz)
                if match:
                    zip_file.extract(file_gz, path_dir_new)
        os.remove(path_last_zip_file)
        self.__path_dir = path_dir_new

    @staticmethod
    def __select_zip_file_where_pmstats_are_located(zip_file):
        files_snapshot = zip_file.namelist()
        file_zip_2011 = []
        for file_zip in files_snapshot:
            match = re.search(r'2011_part', file_zip)
            if match:
                file_zip_2011.append(file_zip)
        last_zip_file = file_zip_2011[-1]
        return last_zip_file

    def __create_dir_snapshot(self):
        name_zip = os.path.basename(self.__path_dir)
        name_snapshot = os.path.splitext(name_zip)[-2]
        path_dir_main = os.path.dirname(self.__path_dir)
        path_dir_new = os.path.join(path_dir_main, name_snapshot)

        if not os.path.isdir(path_dir_new):
            os.mkdir(path_dir_new)

        return path_dir_new

    def __scan_extension(self):
        """

        :return:
        """
        self.__paths_all_files = os.listdir(self.__path_dir)
        extensions = set()
        for file in self.__paths_all_files:
            file_extension = os.path.splitext(file)[-1].lower()
            extensions.add(file_extension)
        return extensions

    def __get_proper_extension_scan_gz(self, extensions):
        """

        :param extensions:
        :return:
        """
        if '.pl' in extensions:
            return '.pl'
        elif '.xml' in extensions:
            return '.xml'
        elif '.gz' in extensions:
            self.__decompress_gz()
            return '.xml'
        elif '.hash' in extensions:
            return '.hash'
        else:
            raise KPINoFilesInDir('No files RTPM/XML/HASH in putted dir')

    def __decompress_gz(self):
        gz_files = self.__get_files('.gz')
        for file_gz in gz_files:
            os.system('gzip -d "{}"'.format(file_gz))

    def __get_files(self, file_extension):
        """

        :param file_extension:
        :return:
        """
        list_path = []
        for file in os.listdir(self.__path_dir):
            if file_extension == os.path.splitext(file)[-1].lower():
                list_path.append(os.path.join(self.__path_dir, file))
        return list_path
